/**
 * Ambient HTTP request context for code running outside a controller's scope.
 *
 * Auto-generated by datrix-codegen-typescript. Do not edit manually.
 *
 * A controller handler receives the request through `@Req()`. A service
 * function (`functions.ts`) does not, yet it is called from handlers and may
 * read the request through the `Request.*` DSL accessors. This module binds
 * the active request in an `AsyncLocalStorage` for the whole async call path
 * of each HTTP request, so those accessors resolve anywhere on that path -- and
 * fail loud on any path that has no request (a job, a queue worker, startup),
 * where a request-scoped value has no meaning.
 *
 * `requestContextMiddleware` is installed by `main.ts` before any other
 * middleware, guard, or handler runs; the guards that later attach the
 * verified principal to `request.user` mutate the same object this store holds.
 */
import { AsyncLocalStorage } from 'node:async_hooks';
import type { NextFunction, Request, Response } from 'express';

type PrincipalCarrier = Request & {
  user?: { id?: string; sub?: string; tenantId?: string };
};

const _requestStore = new AsyncLocalStorage<Request>();

/** Express middleware binding the active request for its whole async call path. */
export function requestContextMiddleware(
  req: Request,
  _res: Response,
  next: NextFunction,
): void {
  _requestStore.run(req, next);
}

/**
 * The HTTP request being served on this call path.
 *
 * @throws Error when no HTTP request is active -- the caller is a job, a queue
 *   worker, or startup code, where request context does not exist.
 */
export function currentRequest(): Request {
  const request = _requestStore.getStore();
  if (request === undefined) {
    throw new Error(
      'No active HTTP request: a Request.* accessor was evaluated outside an HTTP ' +
        'request (a job, a queue worker, or startup). Request context exists only on ' +
        'the call path of a controller handler; pass the value in as a parameter ' +
        'when the function must also run elsewhere.',
    );
  }
  return request;
}

/** Id of the authenticated principal, or `null` on an anonymous request. */
export function currentUserId(): string | null {
  const user = (currentRequest() as PrincipalCarrier).user;
  return user?.id ?? user?.sub ?? null;
}

/** Tenant of the authenticated principal, or `null` when it carries none. */
export function currentTenantId(): string | null {
  return (currentRequest() as PrincipalCarrier).user?.tenantId ?? null;
}

/** Remote address of the active request; empty when the transport reports none. */
export function currentClientIp(): string {
  return currentRequest().ip ?? '';
}
